const body = $input.first().json;
const row = Array.isArray(body) ? body[0] : body;
const data = row && row.data ? row.data : row;

const today = new Date().toISOString().slice(0, 10);
const students = data.students || [];
const attendance = data.attendance || {};

const results = [];
for (const key of Object.keys(attendance)) {
  const date = key.split('|')[0];
  if (date !== today) continue;
  const rec = attendance[key];
  for (const sid of Object.keys(rec)) {
    const entry = rec[sid];
    if (entry.day !== 'absent' && entry.day !== 'late') continue;
    const student = students.find(s => s.id === sid);
    if (!student || !student.guardianPhone) continue;
    const digits = String(student.guardianPhone).replace(/\D/g, '').replace(/^0+/, '');
    results.push({
      studentName: student.name,
      grade: student.grade,
      section: student.section,
      statusAr: entry.day === 'absent' ? 'غائب' : 'متأخر',
      guardianPhone: student.guardianPhone,
      whatsappTo: 'whatsapp:+966' + digits,
      today
    });
  }
}

return results.map(r => ({ json: r }));
